-- =============================================================================
-- Continuous Close Hub: PostgreSQL 16 schema (MVP)
-- Design notes: see DATABASE.md. Based on ARCHITECTURE.md section 4.
--
-- Conventions
--   * Every tenant-owned table has tenant_id, row-level security (FORCE),
--     and UNIQUE (tenant_id, id) so child tables can use composite foreign keys
--     that can never point at another tenant's row.
--   * IDs are UUIDv7 generated by the application. The DB default (v4) is only
--     a fallback.
--   * Money is NUMERIC(20,4) plus an ISO currency code. Never float.
--   * Financial tables are never hard-deleted: the app roles get no DELETE.
--   * Periods are stored as the first day of the month (DATE).
-- =============================================================================

BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;   -- digest() for the audit hash chain

-- -----------------------------------------------------------------------------
-- Roles (cluster-level; created once per environment)
--   app_migrator : owns all objects, runs migrations
--   app_api      : the API service
--   app_worker   : the background worker (sync, AI jobs, posting)
-- -----------------------------------------------------------------------------
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_migrator') THEN
    CREATE ROLE app_migrator NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_api') THEN
    CREATE ROLE app_api NOLOGIN;
  END IF;
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_worker') THEN
    CREATE ROLE app_worker NOLOGIN;
  END IF;
  -- Owns ONLY the sign-in functions. They must find a tenant and user before
  -- any tenant is set, so this role bypasses RLS. Nobody logs in as it.
  IF NOT EXISTS (SELECT 1 FROM pg_roles WHERE rolname = 'app_auth') THEN
    CREATE ROLE app_auth NOLOGIN BYPASSRLS;
  END IF;
END $$;

CREATE SCHEMA core;
CREATE SCHEMA auth;
CREATE SCHEMA tenancy;
CREATE SCHEMA brain;
CREATE SCHEMA close;
CREATE SCHEMA flux;
CREATE SCHEMA journals;
CREATE SCHEMA ai;
CREATE SCHEMA audit;

-- -----------------------------------------------------------------------------
-- Shared domains and helpers
-- -----------------------------------------------------------------------------
CREATE DOMAIN core.money_amount AS NUMERIC(20,4);
CREATE DOMAIN core.currency_code AS CHAR(3) CHECK (VALUE ~ '^[A-Z]{3}$');
CREATE DOMAIN core.period_month AS DATE CHECK (EXTRACT(DAY FROM VALUE) = 1);

-- The tenant for the current transaction. The API runs
--   SET LOCAL app.tenant_id = '<uuid>'
-- at the start of each transaction. Unset or empty means NULL, so no rows match.
CREATE FUNCTION core.current_tenant_id() RETURNS UUID
LANGUAGE sql STABLE AS $$
  SELECT NULLIF(current_setting('app.tenant_id', true), '')::uuid
$$;

-- Generic guard: block UPDATE/DELETE on insert-only tables, even for owners.
CREATE FUNCTION core.forbid_change() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% on %.% is not allowed (insert-only table)',
    TG_OP, TG_TABLE_SCHEMA, TG_TABLE_NAME
    USING ERRCODE = 'insufficient_privilege';
END $$;

-- =============================================================================
-- TENANCY
-- =============================================================================
CREATE TABLE tenancy.tenants (
  id                  UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name                TEXT NOT NULL,
  workos_org_id       TEXT NOT NULL UNIQUE,
  reporting_currency  core.currency_code NOT NULL DEFAULT 'USD',
  status              TEXT NOT NULL DEFAULT 'active'
                      CHECK (status IN ('active', 'suspended', 'closed')),
  created_at          TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE tenancy.entities (
  id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id            UUID NOT NULL REFERENCES tenancy.tenants (id),
  name                 TEXT NOT NULL,
  erp_type             TEXT NOT NULL CHECK (erp_type IN ('netsuite', 'sap')),
  functional_currency  core.currency_code NOT NULL,
  status               TEXT NOT NULL DEFAULT 'setup_required'
                       CHECK (status IN ('setup_required', 'active', 'archived')),
  created_at           TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, name)
);

CREATE TABLE tenancy.users (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id        UUID NOT NULL REFERENCES tenancy.tenants (id),
  workos_user_id   TEXT UNIQUE,                 -- NULL until first sign-in
  email            TEXT NOT NULL,
  display_name     TEXT NOT NULL,
  status           TEXT NOT NULL DEFAULT 'invited'
                   CHECK (status IN ('invited', 'active', 'deactivated')),
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id)
);
CREATE UNIQUE INDEX users_tenant_email_uq ON tenancy.users (tenant_id, lower(email));

-- entity_id NULL = the role applies to every entity in the tenant.
CREATE TABLE tenancy.memberships (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   UUID NOT NULL,
  user_id     UUID NOT NULL,
  entity_id   UUID,
  role        TEXT NOT NULL CHECK (role IN
              ('preparer', 'reviewer', 'approver', 'controller', 'admin', 'auditor')),
  granted_by  UUID,
  granted_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  revoked_at  TIMESTAMPTZ,
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, user_id)    REFERENCES tenancy.users (tenant_id, id),
  FOREIGN KEY (tenant_id, entity_id)  REFERENCES tenancy.entities (tenant_id, id),
  FOREIGN KEY (tenant_id, granted_by) REFERENCES tenancy.users (tenant_id, id)
);
CREATE UNIQUE INDEX memberships_active_uq
  ON tenancy.memberships (tenant_id, user_id, entity_id, role) NULLS NOT DISTINCT
  WHERE revoked_at IS NULL;
CREATE INDEX memberships_user_idx
  ON tenancy.memberships (tenant_id, user_id) WHERE revoked_at IS NULL;

-- =============================================================================
-- AUTH: sessions are looked up before the tenant is known. The app roles get no
-- table access here; they call SECURITY DEFINER functions owned by app_auth.
-- =============================================================================
CREATE TABLE auth.sessions (
  id_hash        BYTEA PRIMARY KEY,            -- sha256 of the cookie value
  tenant_id      UUID NOT NULL REFERENCES tenancy.tenants (id),
  user_id        UUID NOT NULL,
  created_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  last_seen_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  auth_time      TIMESTAMPTZ NOT NULL,         -- last IdP sign-in (step-up checks)
  expires_at     TIMESTAMPTZ NOT NULL,
  revoked_at     TIMESTAMPTZ,
  ip             INET,
  user_agent     TEXT,
  FOREIGN KEY (tenant_id, user_id) REFERENCES tenancy.users (tenant_id, id),
  CHECK (expires_at > created_at)
);
CREATE INDEX sessions_user_active_idx ON auth.sessions (user_id) WHERE revoked_at IS NULL;

-- Called from the SSO callback. Maps the WorkOS organization to a tenant and
-- the WorkOS user to a provisioned user (linking an invited user on first
-- sign-in), then creates the session. Users are never created here: they must
-- already exist via SCIM or an invitation. Returns no row if sign-in is refused.
CREATE FUNCTION auth.create_session(
  p_id_hash         BYTEA,
  p_workos_org_id   TEXT,
  p_workos_user_id  TEXT,
  p_email           TEXT,
  p_lifetime        INTERVAL,
  p_ip              INET,
  p_user_agent      TEXT)
RETURNS TABLE (tenant_id UUID, user_id UUID)
LANGUAGE plpgsql SECURITY DEFINER SET search_path = pg_catalog AS $$
DECLARE
  v_tenant UUID;
  v_user   UUID;
BEGIN
  SELECT t.id INTO v_tenant
    FROM tenancy.tenants t
   WHERE t.workos_org_id = p_workos_org_id AND t.status = 'active';
  IF v_tenant IS NULL THEN
    RETURN;
  END IF;

  SELECT u.id INTO v_user
    FROM tenancy.users u
   WHERE u.tenant_id = v_tenant AND u.workos_user_id = p_workos_user_id
     AND u.status = 'active';

  IF v_user IS NULL THEN
    -- First sign-in of an invited user: link the WorkOS identity by email.
    UPDATE tenancy.users u
       SET workos_user_id = p_workos_user_id, status = 'active'
     WHERE u.tenant_id = v_tenant AND lower(u.email) = lower(p_email)
       AND u.status = 'invited' AND u.workos_user_id IS NULL
    RETURNING u.id INTO v_user;
  END IF;
  IF v_user IS NULL THEN
    RETURN;
  END IF;

  INSERT INTO auth.sessions (id_hash, tenant_id, user_id, auth_time, expires_at, ip, user_agent)
  VALUES (p_id_hash, v_tenant, v_user, now(), now() + p_lifetime, p_ip, p_user_agent);

  tenant_id := v_tenant;
  user_id   := v_user;
  RETURN NEXT;
END $$;

-- Resolve a session cookie to (tenant, user) on every request. Returns no row
-- if the session is expired, idle too long, revoked, or the user is inactive.
CREATE FUNCTION auth.load_session(p_id_hash BYTEA, p_idle_timeout INTERVAL)
RETURNS TABLE (tenant_id UUID, user_id UUID, auth_time TIMESTAMPTZ)
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog AS $$
  UPDATE auth.sessions s
     SET last_seen_at = now()
    FROM tenancy.users u
   WHERE s.id_hash = p_id_hash
     AND s.revoked_at IS NULL
     AND s.expires_at > now()
     AND s.last_seen_at > now() - p_idle_timeout
     AND u.tenant_id = s.tenant_id AND u.id = s.user_id AND u.status = 'active'
  RETURNING s.tenant_id, s.user_id, s.auth_time
$$;

-- Logout (one session) and SCIM deprovisioning (all of a user's sessions).
CREATE FUNCTION auth.revoke_session(p_id_hash BYTEA) RETURNS VOID
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog AS $$
  UPDATE auth.sessions SET revoked_at = now()
   WHERE id_hash = p_id_hash AND revoked_at IS NULL
$$;

CREATE FUNCTION auth.revoke_user_sessions(p_user_id UUID) RETURNS INTEGER
LANGUAGE sql SECURITY DEFINER SET search_path = pg_catalog AS $$
  WITH r AS (
    UPDATE auth.sessions SET revoked_at = now()
     WHERE user_id = p_user_id AND revoked_at IS NULL
    RETURNING 1)
  SELECT count(*)::int FROM r
$$;

-- =============================================================================
-- CORE: idempotency keys for every state-changing request
-- =============================================================================
CREATE TABLE core.idempotency_keys (
  tenant_id        UUID NOT NULL REFERENCES tenancy.tenants (id),
  key              TEXT NOT NULL,
  user_id          UUID NOT NULL,
  request_hash     BYTEA NOT NULL,             -- same key + different body = 422
  response_status  SMALLINT,
  response_body    JSONB,
  created_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  expires_at       TIMESTAMPTZ NOT NULL DEFAULT now() + INTERVAL '24 hours',
  PRIMARY KEY (tenant_id, key),
  FOREIGN KEY (tenant_id, user_id) REFERENCES tenancy.users (tenant_id, id)
);
CREATE INDEX idempotency_expiry_idx ON core.idempotency_keys (expires_at);

-- =============================================================================
-- BRAIN: connections, chart of accounts, balances, lines, FX
-- =============================================================================
CREATE TABLE brain.connections (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     UUID NOT NULL,
  entity_id     UUID NOT NULL,
  erp_type      TEXT NOT NULL CHECK (erp_type IN ('netsuite', 'sap')),
  secret_ref    TEXT NOT NULL,                 -- Secrets Manager ARN; never the secret
  status        TEXT NOT NULL DEFAULT 'pending'
                CHECK (status IN ('pending', 'connected', 'error', 'disabled')),
  last_sync_at  TIMESTAMPTZ,
  last_error    TEXT,
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, entity_id),               -- one ledger per entity
  FOREIGN KEY (tenant_id, entity_id) REFERENCES tenancy.entities (tenant_id, id)
);

CREATE TABLE brain.sync_runs (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      UUID NOT NULL,
  connection_id  UUID NOT NULL,
  trigger        TEXT NOT NULL CHECK (trigger IN ('schedule', 'manual', 'backfill')),
  status         TEXT NOT NULL DEFAULT 'running'
                 CHECK (status IN ('running', 'succeeded', 'partial', 'failed')),
  since_cursor   TEXT,                         -- incremental sync watermark
  stats          JSONB NOT NULL DEFAULT '{}',
  error          TEXT,
  started_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  finished_at    TIMESTAMPTZ,
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, connection_id) REFERENCES brain.connections (tenant_id, id),
  CHECK (finished_at IS NULL OR finished_at >= started_at)
);
CREATE INDEX sync_runs_recent_idx ON brain.sync_runs (tenant_id, connection_id, started_at DESC);

-- Group-level standard chart that entity accounts map to (US-2).
CREATE TABLE brain.standard_accounts (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      UUID NOT NULL REFERENCES tenancy.tenants (id),
  code           TEXT NOT NULL,
  name           TEXT NOT NULL,
  account_class  TEXT NOT NULL
                 CHECK (account_class IN ('asset', 'liability', 'equity', 'revenue', 'expense')),
  parent_id      UUID,
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, code),
  FOREIGN KEY (tenant_id, parent_id) REFERENCES brain.standard_accounts (tenant_id, id)
);

-- Entity-level accounts as they exist in the ERP. parent_account_id builds the
-- flux tree. std_account_id NULL = unmapped (blocks period lock).
CREATE TABLE brain.accounts (
  id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id          UUID NOT NULL,
  entity_id          UUID NOT NULL,
  erp_account_code   TEXT NOT NULL,
  name               TEXT NOT NULL,
  account_class      TEXT NOT NULL
                     CHECK (account_class IN ('asset', 'liability', 'equity', 'revenue', 'expense')),
  statement          TEXT NOT NULL CHECK (statement IN ('bs', 'pl')),
  parent_account_id  UUID,
  std_account_id     UUID,
  is_active          BOOLEAN NOT NULL DEFAULT true,
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, entity_id, erp_account_code),
  FOREIGN KEY (tenant_id, entity_id)         REFERENCES tenancy.entities (tenant_id, id),
  FOREIGN KEY (tenant_id, parent_account_id) REFERENCES brain.accounts (tenant_id, id),
  FOREIGN KEY (tenant_id, std_account_id)    REFERENCES brain.standard_accounts (tenant_id, id),
  CHECK (parent_account_id IS NULL OR parent_account_id <> id)
);
CREATE INDEX accounts_unmapped_idx
  ON brain.accounts (tenant_id, entity_id) WHERE std_account_id IS NULL AND is_active;
CREATE INDEX accounts_parent_idx ON brain.accounts (tenant_id, parent_account_id);

-- Period-end balance per account. Flux reads this, never gl_lines.
CREATE TABLE brain.gl_balances (
  tenant_id          UUID NOT NULL,
  entity_id          UUID NOT NULL,
  account_id         UUID NOT NULL,
  period             core.period_month NOT NULL,
  currency           core.currency_code NOT NULL,   -- functional currency
  amount_functional  core.money_amount NOT NULL,
  amount_reporting   core.money_amount,             -- NULL until an FX rate exists (EC-5)
  sync_run_id        UUID,
  synced_at          TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (tenant_id, entity_id, account_id, period),
  FOREIGN KEY (tenant_id, entity_id)   REFERENCES tenancy.entities (tenant_id, id),
  FOREIGN KEY (tenant_id, account_id)  REFERENCES brain.accounts (tenant_id, id),
  FOREIGN KEY (tenant_id, sync_run_id) REFERENCES brain.sync_runs (tenant_id, id)
);

-- Transaction detail, used for drill-down and AI citations.
-- Partition by RANGE (period) once volume needs it (ARCHITECTURE P-2).
CREATE TABLE brain.gl_lines (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id         UUID NOT NULL,
  entity_id         UUID NOT NULL,
  account_id        UUID NOT NULL,
  period            core.period_month NOT NULL,
  erp_line_ref      TEXT NOT NULL,              -- stable ID from the ERP
  posting_date      DATE NOT NULL,
  amount            core.money_amount NOT NULL, -- signed: debit +, credit -
  currency          core.currency_code NOT NULL,
  memo              TEXT,                       -- untrusted text (prompt-injection risk S-2)
  counterparty_ref  TEXT,                       -- internal ID, not a name (data minimisation)
  dims              JSONB NOT NULL DEFAULT '{}',
  sync_run_id       UUID,
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, entity_id, erp_line_ref),
  FOREIGN KEY (tenant_id, entity_id)   REFERENCES tenancy.entities (tenant_id, id),
  FOREIGN KEY (tenant_id, account_id)  REFERENCES brain.accounts (tenant_id, id),
  FOREIGN KEY (tenant_id, sync_run_id) REFERENCES brain.sync_runs (tenant_id, id)
);
CREATE INDEX gl_lines_account_period_idx
  ON brain.gl_lines (tenant_id, entity_id, account_id, period);

CREATE TABLE brain.fx_rates (
  id         UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id  UUID NOT NULL REFERENCES tenancy.tenants (id),
  period     core.period_month NOT NULL,
  from_ccy   core.currency_code NOT NULL,
  to_ccy     core.currency_code NOT NULL,
  rate_type  TEXT NOT NULL CHECK (rate_type IN ('closing', 'average', 'historical')),
  rate       NUMERIC(24,10) NOT NULL CHECK (rate > 0),
  source     TEXT NOT NULL,
  UNIQUE (tenant_id, period, from_ccy, to_ccy, rate_type),
  CHECK (from_ccy <> to_ccy)
);

-- =============================================================================
-- AI: the AI audit log (insert-only). Defined before the close/flux/journals
-- tables because they reference it.
-- =============================================================================
CREATE TABLE ai.ai_outputs (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id         UUID NOT NULL REFERENCES tenancy.tenants (id),
  kind              TEXT NOT NULL CHECK (kind IN
                    ('variance_explanation', 'context_preview', 'je_draft',
                     'task_verification', 'subtask_draft')),
  outcome           TEXT NOT NULL CHECK (outcome IN
                    ('ok', 'insufficient_data', 'refused', 'failed')),
  model_id          TEXT NOT NULL,
  request_id        TEXT,                      -- provider request ID; NULL if the call failed
  prompt_version    TEXT NOT NULL,
  input_record_ids  UUID[] NOT NULL DEFAULT '{}',
  input_hash        BYTEA NOT NULL,            -- reuse output when inputs are unchanged (P-4)
  output            JSONB,
  citations         JSONB NOT NULL DEFAULT '[]',
  confidence        NUMERIC(4,3) CHECK (confidence BETWEEN 0 AND 1),
  inference_region  TEXT,                      -- logged on every call (D7)
  input_tokens      INTEGER CHECK (input_tokens >= 0),
  output_tokens     INTEGER CHECK (output_tokens >= 0),
  latency_ms        INTEGER CHECK (latency_ms >= 0),
  created_at        TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  CHECK (outcome <> 'ok' OR output IS NOT NULL)
);
CREATE INDEX ai_outputs_reuse_idx ON ai.ai_outputs (tenant_id, kind, input_hash, created_at DESC);
CREATE TRIGGER ai_outputs_insert_only
  BEFORE UPDATE OR DELETE ON ai.ai_outputs
  FOR EACH ROW EXECUTE FUNCTION core.forbid_change();

-- =============================================================================
-- CLOSE: periods, checklist, evidence, comments, reopen
-- =============================================================================
CREATE TABLE close.periods (
  id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id          UUID NOT NULL,
  entity_id          UUID NOT NULL,
  period             core.period_month NOT NULL,
  status             TEXT NOT NULL DEFAULT 'open'
                     CHECK (status IN ('open', 'locked')),
  target_close_day   SMALLINT NOT NULL CHECK (target_close_day BETWEEN 0 AND 60),  -- D+n
  locked_at          TIMESTAMPTZ,
  locked_by          UUID,
  created_at         TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, entity_id, period),
  FOREIGN KEY (tenant_id, entity_id) REFERENCES tenancy.entities (tenant_id, id),
  FOREIGN KEY (tenant_id, locked_by) REFERENCES tenancy.users (tenant_id, id),
  CHECK ((status = 'locked') = (locked_at IS NOT NULL AND locked_by IS NOT NULL))
);

CREATE TABLE close.task_templates (
  id                   UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id            UUID NOT NULL,
  entity_id            UUID NOT NULL,
  phase                TEXT NOT NULL CHECK (phase IN
                       ('pre_close', 'reconciliations', 'accruals', 'intercompany',
                        'compliance', 'board_pack')),
  title                TEXT NOT NULL,
  description          TEXT,
  due_day_offset       SMALLINT NOT NULL,      -- D±n relative to period end
  default_owner_id     UUID,
  default_reviewer_id  UUID,
  requires_evidence    BOOLEAN NOT NULL DEFAULT false,
  is_reconciliation    BOOLEAN NOT NULL DEFAULT false,
  sort_order           INTEGER NOT NULL DEFAULT 0,
  is_active            BOOLEAN NOT NULL DEFAULT true,
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, entity_id)           REFERENCES tenancy.entities (tenant_id, id),
  FOREIGN KEY (tenant_id, default_owner_id)    REFERENCES tenancy.users (tenant_id, id),
  FOREIGN KEY (tenant_id, default_reviewer_id) REFERENCES tenancy.users (tenant_id, id),
  CHECK (default_reviewer_id IS NULL OR default_reviewer_id <> default_owner_id),
  CHECK (NOT is_reconciliation OR requires_evidence)        -- CL-8
);

CREATE TABLE close.task_template_dependencies (
  tenant_id               UUID NOT NULL,
  template_id             UUID NOT NULL,
  depends_on_template_id  UUID NOT NULL,
  PRIMARY KEY (tenant_id, template_id, depends_on_template_id),
  FOREIGN KEY (tenant_id, template_id)            REFERENCES close.task_templates (tenant_id, id),
  FOREIGN KEY (tenant_id, depends_on_template_id) REFERENCES close.task_templates (tenant_id, id),
  CHECK (template_id <> depends_on_template_id)
);

CREATE TABLE close.tasks (
  id                 UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id          UUID NOT NULL,
  period_id          UUID NOT NULL,
  template_id        UUID,
  phase              TEXT NOT NULL CHECK (phase IN
                     ('pre_close', 'reconciliations', 'accruals', 'intercompany',
                      'compliance', 'board_pack')),
  title              TEXT NOT NULL,
  owner_id           UUID,
  reviewer_id        UUID,
  due_day            SMALLINT NOT NULL,
  status             TEXT NOT NULL DEFAULT 'not_started' CHECK (status IN
                     ('not_started', 'in_progress', 'submitted', 'completed', 'rejected')),
  requires_evidence  BOOLEAN NOT NULL DEFAULT false,
  is_reconciliation  BOOLEAN NOT NULL DEFAULT false,
  verified_by_ai     BOOLEAN NOT NULL DEFAULT false,
  ai_output_id       UUID,                     -- the AI verification and its reasoning (CL-2)
  submitted_by       UUID,
  submitted_at       TIMESTAMPTZ,
  signed_off_by      UUID,
  signed_off_at      TIMESTAMPTZ,
  version            INTEGER NOT NULL DEFAULT 1,   -- optimistic concurrency (ETag)
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, period_id)     REFERENCES close.periods (tenant_id, id),
  FOREIGN KEY (tenant_id, template_id)   REFERENCES close.task_templates (tenant_id, id),
  FOREIGN KEY (tenant_id, owner_id)      REFERENCES tenancy.users (tenant_id, id),
  FOREIGN KEY (tenant_id, reviewer_id)   REFERENCES tenancy.users (tenant_id, id),
  FOREIGN KEY (tenant_id, submitted_by)  REFERENCES tenancy.users (tenant_id, id),
  FOREIGN KEY (tenant_id, signed_off_by) REFERENCES tenancy.users (tenant_id, id),
  FOREIGN KEY (tenant_id, ai_output_id)  REFERENCES ai.ai_outputs (tenant_id, id),
  -- SOD (CL-5): reviewer differs from owner; sign-off differs from submitter
  CHECK (reviewer_id IS NULL OR reviewer_id <> owner_id),
  CHECK (signed_off_by IS NULL OR signed_off_by <> submitted_by),
  CHECK (NOT verified_by_ai OR ai_output_id IS NOT NULL),
  CHECK (status <> 'completed' OR signed_off_by IS NOT NULL OR verified_by_ai)
);
CREATE INDEX tasks_period_idx ON close.tasks (tenant_id, period_id, phase);
CREATE INDEX tasks_owner_open_idx ON close.tasks (tenant_id, owner_id)
  WHERE status IN ('not_started', 'in_progress', 'rejected');
CREATE INDEX tasks_reviewer_queue_idx ON close.tasks (tenant_id, reviewer_id)
  WHERE status = 'submitted';

CREATE TABLE close.task_dependencies (
  tenant_id           UUID NOT NULL,
  task_id             UUID NOT NULL,
  depends_on_task_id  UUID NOT NULL,
  PRIMARY KEY (tenant_id, task_id, depends_on_task_id),
  FOREIGN KEY (tenant_id, task_id)            REFERENCES close.tasks (tenant_id, id),
  FOREIGN KEY (tenant_id, depends_on_task_id) REFERENCES close.tasks (tenant_id, id),
  CHECK (task_id <> depends_on_task_id)
);

CREATE TABLE close.subtasks (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   UUID NOT NULL,
  task_id     UUID NOT NULL,
  title       TEXT NOT NULL,
  is_done     BOOLEAN NOT NULL DEFAULT false,
  ai_drafted  BOOLEAN NOT NULL DEFAULT false,
  sort_order  INTEGER NOT NULL DEFAULT 0,
  created_by  UUID,                            -- NULL when drafted by AI
  removed_at  TIMESTAMPTZ,                     -- "delete" is a soft remove (CL-3 logs every change)
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, task_id)    REFERENCES close.tasks (tenant_id, id),
  FOREIGN KEY (tenant_id, created_by) REFERENCES tenancy.users (tenant_id, id),
  CHECK (ai_drafted OR created_by IS NOT NULL)
);
CREATE INDEX subtasks_task_idx ON close.subtasks (tenant_id, task_id) WHERE removed_at IS NULL;

CREATE TABLE close.task_evidence (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     UUID NOT NULL,
  task_id       UUID NOT NULL,
  s3_key        TEXT NOT NULL UNIQUE,          -- under the tenant's prefix
  file_name     TEXT NOT NULL,
  content_type  TEXT NOT NULL,
  size_bytes    BIGINT NOT NULL CHECK (size_bytes > 0 AND size_bytes <= 104857600),  -- 100 MB
  sha256        BYTEA NOT NULL,
  scan_status   TEXT NOT NULL DEFAULT 'pending'
                CHECK (scan_status IN ('pending', 'clean', 'infected')),   -- S-10
  uploaded_by   UUID NOT NULL,
  uploaded_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, task_id)     REFERENCES close.tasks (tenant_id, id),
  FOREIGN KEY (tenant_id, uploaded_by) REFERENCES tenancy.users (tenant_id, id)
);
CREATE INDEX task_evidence_task_idx ON close.task_evidence (tenant_id, task_id);

-- Comments are attached to several kinds of record (polymorphic). Integrity of
-- subject_id is checked in the service layer; comments are append-only.
CREATE TABLE close.comments (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     UUID NOT NULL,
  subject_type  TEXT NOT NULL CHECK (subject_type IN
                ('task', 'variance', 'je_draft', 'context_note')),
  subject_id    UUID NOT NULL,
  author_id     UUID NOT NULL,
  body          TEXT NOT NULL CHECK (length(body) BETWEEN 1 AND 10000),
  created_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, author_id) REFERENCES tenancy.users (tenant_id, id)
);
CREATE INDEX comments_subject_idx ON close.comments (tenant_id, subject_type, subject_id, created_at);
CREATE TRIGGER comments_insert_only
  BEFORE UPDATE OR DELETE ON close.comments
  FOR EACH ROW EXECUTE FUNCTION core.forbid_change();

CREATE TABLE close.reopen_requests (
  id            UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id     UUID NOT NULL,
  period_id     UUID NOT NULL,
  reason        TEXT NOT NULL CHECK (length(reason) >= 10),
  requested_by  UUID NOT NULL,
  requested_at  TIMESTAMPTZ NOT NULL DEFAULT now(),
  status        TEXT NOT NULL DEFAULT 'pending'
                CHECK (status IN ('pending', 'approved', 'rejected')),
  decided_by    UUID,
  decided_at    TIMESTAMPTZ,
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, period_id)    REFERENCES close.periods (tenant_id, id),
  FOREIGN KEY (tenant_id, requested_by) REFERENCES tenancy.users (tenant_id, id),
  FOREIGN KEY (tenant_id, decided_by)   REFERENCES tenancy.users (tenant_id, id),
  CHECK (decided_by IS NULL OR decided_by <> requested_by),          -- SOD
  CHECK ((status = 'pending') = (decided_by IS NULL))
);
CREATE UNIQUE INDEX reopen_one_pending_uq
  ON close.reopen_requests (tenant_id, period_id) WHERE status = 'pending';

-- =============================================================================
-- FLUX: thresholds, variances, attribution, AI context
-- =============================================================================
-- Versioned, never overwritten. account_class NULL = entity default.
CREATE TABLE flux.thresholds (
  id              UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id       UUID NOT NULL,
  entity_id       UUID NOT NULL,
  account_class   TEXT CHECK (account_class IN
                  ('asset', 'liability', 'equity', 'revenue', 'expense')),
  abs_amount      core.money_amount NOT NULL CHECK (abs_amount >= 0),
  pct             NUMERIC(7,4) NOT NULL CHECK (pct >= 0),   -- 10% stored as 10.0000
  version         INTEGER NOT NULL CHECK (version >= 1),
  effective_from  core.period_month NOT NULL,
  created_by      UUID NOT NULL,
  created_at      TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, entity_id)  REFERENCES tenancy.entities (tenant_id, id),
  FOREIGN KEY (tenant_id, created_by) REFERENCES tenancy.users (tenant_id, id)
);
CREATE UNIQUE INDEX thresholds_version_uq
  ON flux.thresholds (tenant_id, entity_id, account_class, version) NULLS NOT DISTINCT;
CREATE TRIGGER thresholds_insert_only
  BEFORE UPDATE OR DELETE ON flux.thresholds
  FOR EACH ROW EXECUTE FUNCTION core.forbid_change();

-- Precomputed by the worker after each sync (ARCHITECTURE P-1).
CREATE TABLE flux.variances (
  id                        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                 UUID NOT NULL,
  period_id                 UUID NOT NULL,
  account_id                UUID NOT NULL,
  currency                  core.currency_code NOT NULL,
  prior_amount              core.money_amount NOT NULL,
  current_amount            core.money_amount NOT NULL,
  delta                     core.money_amount NOT NULL,
  delta_pct                 NUMERIC(12,4),     -- NULL when prior is zero (EC-3)
  is_flagged                BOOLEAN NOT NULL,
  threshold_id              UUID NOT NULL,     -- which threshold version flagged it (S-11)
  status                    TEXT NOT NULL CHECK (status IN
                            ('not_flagged', 'open', 'needs_manual', 'explained',
                             'signed_off', 'exception')),
  explanation_ai_output_id  UUID,
  input_hash                BYTEA NOT NULL,    -- inputs to the explanation (reuse, P-4)
  changed_after_signoff     BOOLEAN NOT NULL DEFAULT false,  -- EC-6 (proposed, PRD Q6)
  signed_off_by             UUID,
  signed_off_at             TIMESTAMPTZ,
  exception_reason          TEXT,
  computed_at               TIMESTAMPTZ NOT NULL DEFAULT now(),
  version                   INTEGER NOT NULL DEFAULT 1,
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, period_id, account_id),
  FOREIGN KEY (tenant_id, period_id)    REFERENCES close.periods (tenant_id, id),
  FOREIGN KEY (tenant_id, account_id)   REFERENCES brain.accounts (tenant_id, id),
  FOREIGN KEY (tenant_id, threshold_id) REFERENCES flux.thresholds (tenant_id, id),
  FOREIGN KEY (tenant_id, explanation_ai_output_id) REFERENCES ai.ai_outputs (tenant_id, id),
  FOREIGN KEY (tenant_id, signed_off_by) REFERENCES tenancy.users (tenant_id, id),
  CHECK (delta = current_amount - prior_amount),
  CHECK (is_flagged = (status <> 'not_flagged')),
  CHECK ((status IN ('signed_off', 'exception')) = (signed_off_by IS NOT NULL)),
  CHECK (status <> 'exception' OR exception_reason IS NOT NULL)
);
CREATE INDEX variances_flagged_idx ON flux.variances (tenant_id, period_id, status)
  WHERE is_flagged;

CREATE TABLE flux.variance_attributions (
  id                UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id         UUID NOT NULL,
  variance_id       UUID NOT NULL,
  child_account_id  UUID NOT NULL,
  amount            core.money_amount NOT NULL,
  share_pct         NUMERIC(7,4) NOT NULL,
  UNIQUE (tenant_id, variance_id, child_account_id),
  FOREIGN KEY (tenant_id, variance_id)      REFERENCES flux.variances (tenant_id, id),
  FOREIGN KEY (tenant_id, child_account_id) REFERENCES brain.accounts (tenant_id, id)
);

-- PRD section 10.2. Pending notes only ever appear in previews.
CREATE TABLE flux.context_notes (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      UUID NOT NULL,
  scope          TEXT NOT NULL CHECK (scope IN ('account', 'account_group', 'cross_entity')),
  entity_id      UUID,                         -- NULL only for cross_entity
  account_id     UUID,                         -- account, or parent account for a group
  std_account_id UUID,                         -- cross_entity notes target the standard chart
  text           TEXT NOT NULL CHECK (length(text) BETWEEN 3 AND 2000),
  status         TEXT NOT NULL DEFAULT 'pending'
                 CHECK (status IN ('pending', 'approved', 'rejected', 'retired')),
  proposed_by    UUID NOT NULL,
  proposed_at    TIMESTAMPTZ NOT NULL DEFAULT now(),
  decided_by     UUID,
  decided_at     TIMESTAMPTZ,
  review_by      DATE,                          -- NULL = no expiry (Controller approval only)
  version        INTEGER NOT NULL DEFAULT 1,
  supersedes_id  UUID,
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, entity_id)      REFERENCES tenancy.entities (tenant_id, id),
  FOREIGN KEY (tenant_id, account_id)     REFERENCES brain.accounts (tenant_id, id),
  FOREIGN KEY (tenant_id, std_account_id) REFERENCES brain.standard_accounts (tenant_id, id),
  FOREIGN KEY (tenant_id, proposed_by)    REFERENCES tenancy.users (tenant_id, id),
  FOREIGN KEY (tenant_id, decided_by)     REFERENCES tenancy.users (tenant_id, id),
  FOREIGN KEY (tenant_id, supersedes_id)  REFERENCES flux.context_notes (tenant_id, id),
  CHECK (decided_by IS NULL OR decided_by <> proposed_by),            -- SOD
  CHECK ((status = 'pending') = (decided_by IS NULL)),
  CHECK (
    (scope IN ('account', 'account_group') AND entity_id IS NOT NULL AND account_id IS NOT NULL)
    OR (scope = 'cross_entity' AND entity_id IS NULL AND std_account_id IS NOT NULL)
  )
);
CREATE INDEX context_notes_active_idx ON flux.context_notes (tenant_id, entity_id, account_id)
  WHERE status = 'approved';
CREATE INDEX context_notes_review_idx ON flux.context_notes (tenant_id, review_by)
  WHERE status = 'approved' AND review_by IS NOT NULL;

-- Which context notes each explanation used (PRD 10.2 "visibility").
CREATE TABLE flux.variance_context_links (
  tenant_id        UUID NOT NULL,
  variance_id      UUID NOT NULL,
  context_note_id  UUID NOT NULL,
  ai_output_id     UUID NOT NULL,
  PRIMARY KEY (tenant_id, ai_output_id, context_note_id),
  FOREIGN KEY (tenant_id, variance_id)     REFERENCES flux.variances (tenant_id, id),
  FOREIGN KEY (tenant_id, context_note_id) REFERENCES flux.context_notes (tenant_id, id),
  FOREIGN KEY (tenant_id, ai_output_id)    REFERENCES ai.ai_outputs (tenant_id, id)
);
CREATE INDEX variance_context_note_idx ON flux.variance_context_links (tenant_id, context_note_id);

-- =============================================================================
-- JOURNALS: drafts, lines, approvals, posting
-- =============================================================================
-- Second-approver rule per entity (JE-4). Versioned, never overwritten.
CREATE TABLE journals.approval_policies (
  id                      UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id               UUID NOT NULL,
  entity_id               UUID NOT NULL,
  second_approval_above   core.money_amount NOT NULL CHECK (second_approval_above >= 0),
  currency                core.currency_code NOT NULL,
  version                 INTEGER NOT NULL CHECK (version >= 1),
  effective_from          core.period_month NOT NULL,
  created_by              UUID NOT NULL,
  created_at              TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, entity_id, version),
  FOREIGN KEY (tenant_id, entity_id)  REFERENCES tenancy.entities (tenant_id, id),
  FOREIGN KEY (tenant_id, created_by) REFERENCES tenancy.users (tenant_id, id)
);
CREATE TRIGGER approval_policies_insert_only
  BEFORE UPDATE OR DELETE ON journals.approval_policies
  FOR EACH ROW EXECUTE FUNCTION core.forbid_change();

CREATE TABLE journals.je_drafts (
  id                        UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id                 UUID NOT NULL,
  period_id                 UUID NOT NULL,
  je_type                   TEXT NOT NULL CHECK (je_type IN ('correction', 'reclass', 'accrual')),
  source_type               TEXT NOT NULL CHECK (source_type IN ('variance', 'manual')),
                            -- v1 adds 'accrual_proposal', 'contract'
  source_variance_id        UUID,
  description               TEXT NOT NULL,
  status                    TEXT NOT NULL DEFAULT 'draft' CHECK (status IN
                            ('draft', 'submitted', 'approved', 'rejected',
                             'posting', 'posted', 'post_failed', 'withdrawn')),
  created_by_ai             BOOLEAN NOT NULL DEFAULT false,
  ai_output_id              UUID,
  preparer_id               UUID,              -- whoever submitted / last edited (SOD)
  currency                  core.currency_code NOT NULL,
  total_amount              core.money_amount NOT NULL DEFAULT 0,  -- sum of debits; derived
  approval_policy_id        UUID,
  requires_second_approval  BOOLEAN NOT NULL DEFAULT false,
  source_changed            BOOLEAN NOT NULL DEFAULT false,  -- EC-20 (proposed, PRD Q6)
  version                   INTEGER NOT NULL DEFAULT 1,      -- bumps on every edit; ETag + idempotency
  erp_doc_number            TEXT,
  posted_at                 TIMESTAMPTZ,
  created_at                TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, period_id)          REFERENCES close.periods (tenant_id, id),
  FOREIGN KEY (tenant_id, source_variance_id) REFERENCES flux.variances (tenant_id, id),
  FOREIGN KEY (tenant_id, ai_output_id)       REFERENCES ai.ai_outputs (tenant_id, id),
  FOREIGN KEY (tenant_id, preparer_id)        REFERENCES tenancy.users (tenant_id, id),
  FOREIGN KEY (tenant_id, approval_policy_id) REFERENCES journals.approval_policies (tenant_id, id),
  CHECK ((source_type = 'variance') = (source_variance_id IS NOT NULL)),
  CHECK (NOT created_by_ai OR ai_output_id IS NOT NULL),
  CHECK (status = 'draft' OR preparer_id IS NOT NULL),
  CHECK ((status = 'posted') = (erp_doc_number IS NOT NULL AND posted_at IS NOT NULL)),
  CHECK (total_amount >= 0)
);
CREATE INDEX je_drafts_period_status_idx ON journals.je_drafts (tenant_id, period_id, status);
CREATE INDEX je_drafts_source_idx ON journals.je_drafts (tenant_id, source_variance_id);

CREATE TABLE journals.je_lines (
  id          UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id   UUID NOT NULL,
  draft_id    UUID NOT NULL,
  line_no     SMALLINT NOT NULL CHECK (line_no >= 1),
  account_id  UUID NOT NULL,
  debit       core.money_amount NOT NULL DEFAULT 0 CHECK (debit >= 0),
  credit      core.money_amount NOT NULL DEFAULT 0 CHECK (credit >= 0),
  dims        JSONB NOT NULL DEFAULT '{}',
  memo        TEXT,
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, draft_id, line_no),
  FOREIGN KEY (tenant_id, draft_id)   REFERENCES journals.je_drafts (tenant_id, id),
  FOREIGN KEY (tenant_id, account_id) REFERENCES brain.accounts (tenant_id, id),
  CHECK ((debit > 0 AND credit = 0) OR (credit > 0 AND debit = 0))   -- one side per line
);

-- One row per entry per approval level, even inside a batch (JE-3).
CREATE TABLE journals.approval_batches (
  id           UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id    UUID NOT NULL,
  period_id    UUID NOT NULL,
  approver_id  UUID NOT NULL,
  entry_count  INTEGER NOT NULL CHECK (entry_count > 0),
  created_at   TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  FOREIGN KEY (tenant_id, period_id)   REFERENCES close.periods (tenant_id, id),
  FOREIGN KEY (tenant_id, approver_id) REFERENCES tenancy.users (tenant_id, id)
);

CREATE TABLE journals.approvals (
  id             UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id      UUID NOT NULL,
  draft_id       UUID NOT NULL,
  draft_version  INTEGER NOT NULL,             -- the exact version that was approved
  level          SMALLINT NOT NULL CHECK (level IN (1, 2)),
  approver_id    UUID NOT NULL,
  decision       TEXT NOT NULL CHECK (decision IN ('approved', 'rejected')),
  comment        TEXT,
  batch_id       UUID,
  decided_at     TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, draft_id, draft_version, level),
  FOREIGN KEY (tenant_id, draft_id)    REFERENCES journals.je_drafts (tenant_id, id),
  FOREIGN KEY (tenant_id, approver_id) REFERENCES tenancy.users (tenant_id, id),
  FOREIGN KEY (tenant_id, batch_id)    REFERENCES journals.approval_batches (tenant_id, id),
  CHECK (decision <> 'rejected' OR comment IS NOT NULL)
);
CREATE INDEX approvals_draft_idx ON journals.approvals (tenant_id, draft_id);
CREATE TRIGGER approvals_insert_only
  BEFORE UPDATE OR DELETE ON journals.approvals
  FOR EACH ROW EXECUTE FUNCTION core.forbid_change();

CREATE TABLE journals.posting_attempts (
  id               UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  tenant_id        UUID NOT NULL,
  draft_id         UUID NOT NULL,
  attempt_no       SMALLINT NOT NULL CHECK (attempt_no >= 1),
  idempotency_key  TEXT NOT NULL,              -- draft id + version; sent as the ERP external ID
  request_hash     BYTEA NOT NULL,
  status           TEXT NOT NULL DEFAULT 'pending'
                   CHECK (status IN ('pending', 'succeeded', 'failed', 'unknown')),
  erp_doc_number   TEXT,
  error_code       TEXT,
  error_message    TEXT,
  erp_response     JSONB,
  started_at       TIMESTAMPTZ NOT NULL DEFAULT now(),
  finished_at      TIMESTAMPTZ,
  UNIQUE (tenant_id, id),
  UNIQUE (tenant_id, draft_id, attempt_no),
  FOREIGN KEY (tenant_id, draft_id) REFERENCES journals.je_drafts (tenant_id, id),
  CHECK (status <> 'succeeded' OR erp_doc_number IS NOT NULL)
);
CREATE INDEX posting_attempts_key_idx ON journals.posting_attempts (tenant_id, idempotency_key);
-- At most one successful post per draft, ever (S-4).
CREATE UNIQUE INDEX posting_one_success_uq
  ON journals.posting_attempts (tenant_id, draft_id) WHERE status = 'succeeded';

-- =============================================================================
-- AUDIT: append-only event log with a per-tenant hash chain (S-6)
-- =============================================================================
CREATE TABLE audit.events (
  id            BIGINT GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  tenant_id     UUID NOT NULL REFERENCES tenancy.tenants (id),
  occurred_at   TIMESTAMPTZ NOT NULL DEFAULT clock_timestamp(),
  actor_type    TEXT NOT NULL CHECK (actor_type IN ('user', 'ai', 'system')),
  actor_id      UUID,                          -- user ID; NULL for system
  action        TEXT NOT NULL,                 -- e.g. 'je_draft.approved'
  subject_type  TEXT NOT NULL,
  subject_id    UUID NOT NULL,
  before        JSONB,
  after         JSONB,
  request_id    TEXT,
  prev_hash     BYTEA,                          -- NULL only for a tenant's first event
  hash          BYTEA NOT NULL,
  CHECK (actor_type <> 'user' OR actor_id IS NOT NULL)
);
CREATE INDEX events_subject_idx ON audit.events (tenant_id, subject_type, subject_id, id);
CREATE INDEX events_time_idx ON audit.events (tenant_id, occurred_at);

-- Chain each tenant's events: hash = sha256(prev_hash || this row's content).
-- The advisory lock serialises inserts per tenant so the chain has no forks.
CREATE FUNCTION audit.chain_event() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  PERFORM pg_advisory_xact_lock(hashtextextended(NEW.tenant_id::text, 0));
  SELECT e.hash INTO NEW.prev_hash
    FROM audit.events e
   WHERE e.tenant_id = NEW.tenant_id
   ORDER BY e.id DESC
   LIMIT 1;
  NEW.hash := digest(
    coalesce(NEW.prev_hash, '\x'::bytea) ||
    convert_to(concat_ws('|',
      NEW.tenant_id, NEW.occurred_at, NEW.actor_type, NEW.actor_id, NEW.action,
      NEW.subject_type, NEW.subject_id, NEW.before::text, NEW.after::text, NEW.request_id),
      'UTF8'),
    'sha256');
  RETURN NEW;
END $$;

CREATE TRIGGER events_chain
  BEFORE INSERT ON audit.events
  FOR EACH ROW EXECUTE FUNCTION audit.chain_event();
CREATE TRIGGER events_insert_only
  BEFORE UPDATE OR DELETE ON audit.events
  FOR EACH ROW EXECUTE FUNCTION core.forbid_change();

-- =============================================================================
-- BUSINESS-RULE TRIGGERS
-- =============================================================================

-- (1) Locked periods reject changes (PRD section 10, item 7).
CREATE FUNCTION close.guard_locked_period() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_period_id UUID;
  v_status    TEXT;
BEGIN
  v_period_id := CASE WHEN TG_OP = 'DELETE' THEN OLD.period_id ELSE NEW.period_id END;
  SELECT status INTO v_status FROM close.periods WHERE id = v_period_id;
  IF v_status = 'locked' THEN
    RAISE EXCEPTION 'Period % is locked; request a reopen first', v_period_id
      USING ERRCODE = 'check_violation';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;

CREATE TRIGGER tasks_period_lock     BEFORE INSERT OR UPDATE OR DELETE ON close.tasks
  FOR EACH ROW EXECUTE FUNCTION close.guard_locked_period();
CREATE TRIGGER variances_period_lock BEFORE INSERT OR UPDATE OR DELETE ON flux.variances
  FOR EACH ROW EXECUTE FUNCTION close.guard_locked_period();
CREATE TRIGGER je_drafts_period_lock BEFORE INSERT OR UPDATE OR DELETE ON journals.je_drafts
  FOR EACH ROW EXECUTE FUNCTION close.guard_locked_period();

-- (2) A draft must balance (and have >= 2 lines) before it leaves 'draft',
--     and its lines are frozen once it does (JE-6).
CREATE FUNCTION journals.check_draft_on_submit() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_debit  NUMERIC;
  v_credit NUMERIC;
  v_lines  INTEGER;
BEGIN
  IF OLD.status = 'draft' AND NEW.status = 'submitted' THEN
    SELECT coalesce(sum(debit), 0), coalesce(sum(credit), 0), count(*)
      INTO v_debit, v_credit, v_lines
      FROM journals.je_lines
     WHERE tenant_id = NEW.tenant_id AND draft_id = NEW.id;
    IF v_lines < 2 THEN
      RAISE EXCEPTION 'Draft % needs at least 2 lines', NEW.id USING ERRCODE = 'check_violation';
    END IF;
    IF v_debit <> v_credit THEN
      RAISE EXCEPTION 'Draft % does not balance (debits %, credits %)', NEW.id, v_debit, v_credit
        USING ERRCODE = 'check_violation';
    END IF;
    NEW.total_amount := v_debit;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER je_drafts_submit_check
  BEFORE UPDATE OF status ON journals.je_drafts
  FOR EACH ROW EXECUTE FUNCTION journals.check_draft_on_submit();

CREATE FUNCTION journals.freeze_lines() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_status TEXT;
BEGIN
  SELECT status INTO v_status
    FROM journals.je_drafts
   WHERE id = CASE WHEN TG_OP = 'DELETE' THEN OLD.draft_id ELSE NEW.draft_id END;
  IF v_status <> 'draft' THEN
    RAISE EXCEPTION 'Lines of a % draft cannot change', v_status USING ERRCODE = 'check_violation';
  END IF;
  RETURN CASE WHEN TG_OP = 'DELETE' THEN OLD ELSE NEW END;
END $$;

CREATE TRIGGER je_lines_frozen
  BEFORE INSERT OR UPDATE OR DELETE ON journals.je_lines
  FOR EACH ROW EXECUTE FUNCTION journals.freeze_lines();

-- (3) SOD on approvals (JE-4): the approver is not the preparer, the draft is
--     submitted, the approved version is current, and level 2 is a different
--     person from level 1.
CREATE FUNCTION journals.check_approval_sod() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  d journals.je_drafts%ROWTYPE;
  v_level1_approver UUID;
BEGIN
  SELECT * INTO d FROM journals.je_drafts
   WHERE tenant_id = NEW.tenant_id AND id = NEW.draft_id
   FOR UPDATE;
  IF d.status <> 'submitted' THEN
    RAISE EXCEPTION 'Draft % is %, not submitted', d.id, d.status USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.draft_version <> d.version THEN
    RAISE EXCEPTION 'Draft % changed since it was reviewed (v% vs v%)', d.id, NEW.draft_version, d.version
      USING ERRCODE = 'serialization_failure';
  END IF;
  IF NEW.approver_id = d.preparer_id THEN
    RAISE EXCEPTION 'Preparer cannot approve their own entry' USING ERRCODE = 'check_violation';
  END IF;
  IF NEW.level = 2 THEN
    IF NOT d.requires_second_approval THEN
      RAISE EXCEPTION 'Draft % does not need a second approval', d.id USING ERRCODE = 'check_violation';
    END IF;
    SELECT approver_id INTO v_level1_approver FROM journals.approvals
     WHERE tenant_id = NEW.tenant_id AND draft_id = NEW.draft_id
       AND draft_version = NEW.draft_version AND level = 1 AND decision = 'approved';
    IF v_level1_approver IS NULL THEN
      RAISE EXCEPTION 'Level 1 approval is missing' USING ERRCODE = 'check_violation';
    END IF;
    IF v_level1_approver = NEW.approver_id THEN
      RAISE EXCEPTION 'Second approver must be a different person' USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER approvals_sod
  BEFORE INSERT ON journals.approvals
  FOR EACH ROW EXECUTE FUNCTION journals.check_approval_sod();

-- (4) A draft can only become 'approved' when every required approval exists
--     for its current version.
CREATE FUNCTION journals.check_draft_approved() RETURNS trigger
LANGUAGE plpgsql AS $$
DECLARE
  v_needed SMALLINT;
  v_have   INTEGER;
BEGIN
  IF NEW.status = 'approved' AND OLD.status <> 'approved' THEN
    v_needed := CASE WHEN NEW.requires_second_approval THEN 2 ELSE 1 END;
    SELECT count(*) INTO v_have FROM journals.approvals
     WHERE tenant_id = NEW.tenant_id AND draft_id = NEW.id
       AND draft_version = NEW.version AND decision = 'approved';
    IF v_have < v_needed THEN
      RAISE EXCEPTION 'Draft % has % of % required approvals', NEW.id, v_have, v_needed
        USING ERRCODE = 'check_violation';
    END IF;
  END IF;
  RETURN NEW;
END $$;

CREATE TRIGGER je_drafts_approved_check
  BEFORE UPDATE OF status ON journals.je_drafts
  FOR EACH ROW EXECUTE FUNCTION journals.check_draft_approved();

-- =============================================================================
-- ROW-LEVEL SECURITY: one policy per tenant-owned table
-- =============================================================================
DO $$
DECLARE
  t RECORD;
BEGIN
  FOR t IN
    SELECT table_schema, table_name
      FROM information_schema.columns
     WHERE column_name = 'tenant_id'
       AND table_schema IN ('core', 'tenancy', 'brain', 'close', 'flux', 'journals', 'ai', 'audit')
  LOOP
    EXECUTE format('ALTER TABLE %I.%I ENABLE ROW LEVEL SECURITY', t.table_schema, t.table_name);
    EXECUTE format('ALTER TABLE %I.%I FORCE ROW LEVEL SECURITY', t.table_schema, t.table_name);
    EXECUTE format(
      'CREATE POLICY tenant_isolation ON %I.%I
         USING (tenant_id = core.current_tenant_id())
         WITH CHECK (tenant_id = core.current_tenant_id())',
      t.table_schema, t.table_name);
  END LOOP;
END $$;

-- tenants has no tenant_id column: a tenant may only see itself.
ALTER TABLE tenancy.tenants ENABLE ROW LEVEL SECURITY;
ALTER TABLE tenancy.tenants FORCE ROW LEVEL SECURITY;
CREATE POLICY tenant_self ON tenancy.tenants
  USING (id = core.current_tenant_id());

-- =============================================================================
-- OWNERSHIP AND GRANTS
-- =============================================================================
DO $$
DECLARE
  s TEXT;
  r RECORD;
BEGIN
  FOREACH s IN ARRAY ARRAY['core', 'auth', 'tenancy', 'brain', 'close', 'flux', 'journals', 'ai', 'audit']
  LOOP
    EXECUTE format('ALTER SCHEMA %I OWNER TO app_migrator', s);
    FOR r IN SELECT tablename FROM pg_tables WHERE schemaname = s AND s <> 'auth' LOOP
      EXECUTE format('ALTER TABLE %I.%I OWNER TO app_migrator', s, r.tablename);
    END LOOP;
  END LOOP;
END $$;

GRANT USAGE ON SCHEMA core, tenancy, brain, close, flux, journals, ai, audit TO app_api, app_worker;
GRANT EXECUTE ON FUNCTION core.current_tenant_id() TO app_api, app_worker;

-- Default: read + insert + update. DELETE is never granted on financial data.
GRANT SELECT, INSERT, UPDATE
  ON ALL TABLES IN SCHEMA tenancy, brain, close, flux, journals
  TO app_api, app_worker;

-- Tenants are created by internal tooling only.
REVOKE INSERT, UPDATE ON tenancy.tenants FROM app_api, app_worker;

-- Insert-only tables: no UPDATE for anyone (triggers also block it).
REVOKE UPDATE ON close.comments, flux.thresholds, journals.approvals,
                 journals.approval_policies FROM app_api, app_worker;
GRANT SELECT, INSERT ON ai.ai_outputs, audit.events TO app_api, app_worker;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA audit TO app_api, app_worker;

-- Idempotency records expire, so these may be deleted by a cleanup job.
GRANT SELECT, INSERT, UPDATE, DELETE ON core.idempotency_keys TO app_api;

-- Only the worker records ERP posting attempts and writes ledger data.
REVOKE INSERT, UPDATE ON journals.posting_attempts FROM app_api;
REVOKE INSERT, UPDATE ON brain.gl_balances, brain.gl_lines, brain.sync_runs FROM app_api;

-- Sessions: owned by app_auth, reachable only through its SECURITY DEFINER
-- functions. app_auth may read tenants/users and link an invited user.
GRANT USAGE ON SCHEMA auth, tenancy TO app_auth;
ALTER TABLE auth.sessions OWNER TO app_auth;
GRANT SELECT ON tenancy.tenants, tenancy.users TO app_auth;
GRANT UPDATE (workos_user_id, status) ON tenancy.users TO app_auth;

ALTER FUNCTION auth.create_session(BYTEA, TEXT, TEXT, TEXT, INTERVAL, INET, TEXT) OWNER TO app_auth;
ALTER FUNCTION auth.load_session(BYTEA, INTERVAL) OWNER TO app_auth;
ALTER FUNCTION auth.revoke_session(BYTEA) OWNER TO app_auth;
ALTER FUNCTION auth.revoke_user_sessions(UUID) OWNER TO app_auth;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA auth FROM PUBLIC;

GRANT USAGE ON SCHEMA auth TO app_api;
GRANT EXECUTE ON FUNCTION
  auth.create_session(BYTEA, TEXT, TEXT, TEXT, INTERVAL, INET, TEXT),
  auth.load_session(BYTEA, INTERVAL),
  auth.revoke_session(BYTEA),
  auth.revoke_user_sessions(UUID)
  TO app_api;

COMMIT;
